import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { API, graphqlOperation } from "aws-amplify";
import { create_list_edit_delete_asset_retailers } from "@/graphql/mutations.js";
import SnackBar from "@/components/SnackBar.vue";
import DeleteRetailer from "@/components/Asset/Popups/DeleteRetailer.vue";
import AddRetailer from "@/components/Asset/Popups/AddRetailer.vue";
import EditRetailer from "@/components/Asset/Popups/EditRetailer.vue";
export default {
  components: {
    AddRetailer,
    EditRetailer,
    DeleteRetailer,
    SnackBar
  },
  emits: ['backAction'],
  data() {
    return {
      createretailer: false,
      retaileredition: false,
      retaileredeletion: false,
      SnackBarComponent: {},
      componentcheck: 0,
      fixed: true,
      retailerRecords: [],
      tableLoading: false,
      retaileritem: {},
      retailerHeaders: [{
        title: "Distributor",
        key: "asset_distributor_name",
        sortable: false
      }, {
        title: "Name",
        key: "asset_retailer_name",
        sortable: false
      }, {
        title: "Contact Name",
        key: "contact_name",
        sortable: false
      }, {
        title: "Code",
        key: "asset_retailer_code",
        sortable: false
      }, {
        title: "Email ID",
        key: "asset_retailer_email",
        sortable: false
      }, {
        title: "Contact No",
        key: "full_contact_no",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0,
      searchQuery: "",
      filteredRetailerRecords: []
    };
  },
  mounted() {
    this.updateWindowHeight();
    window.addEventListener('resize', this.updateWindowHeight);
    this.fetch_retailerlist();
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  computed: {
    totalCount() {
      return this.filteredRetailerRecords.length;
    },
    pageCount() {
      return Math.ceil(this.filteredRetailerRecords.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    open_editdailog(item) {
      this.componentcheck = 2;
      this.retaileredition = true;
      this.retaileritem = item;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createretailer = false;
      this.retaileredition = false;
      this.retaileredeletion = false;
      this.fetch_retailerlist();
    },
    open_deletedailog(item) {
      this.componentcheck = 3;
      this.retaileredeletion = true;
      this.retaileritem = item;
    },
    add_retailer() {
      this.componentcheck = 1;
      this.createretailer = true;
    },
    async fetch_retailerlist() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_asset_retailers, {
          input: {
            organization_id: data.organization.organization_id,
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.create_list_edit_delete_asset_retailers);
        this.retailerRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.retailerRecords = response.data;
          this.filterRetailers();
          this.tableLoading = false;
          this.updatePageItems();
        } else {
          this.retailerRecords = [];
          this.filteredRetailerRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.retailerRecords = [];
        this.filteredRetailerRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    onSearchChange() {
      this.currentPage = 1;
      this.filterRetailers();
      this.updatePageItems();
    },
    filterRetailers() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        this.filteredRetailerRecords = this.retailerRecords;
      } else {
        const query = this.searchQuery.toLowerCase().trim();
        this.filteredRetailerRecords = this.retailerRecords.filter(retailer => {
          return retailer.asset_retailer_name && retailer.asset_retailer_name.toLowerCase().includes(query) || retailer.asset_retailer_code && retailer.asset_retailer_code.toLowerCase().includes(query) || retailer.contact_name && retailer.contact_name.toLowerCase().includes(query) || retailer.asset_retailer_email && retailer.asset_retailer_email.toLowerCase().includes(query) || retailer.asset_distributor_name && retailer.asset_distributor_name.toLowerCase().includes(query) || retailer.full_contact_no && retailer.full_contact_no.toString().includes(query);
        });
      }
    },
    updatePageItems() {
      const startIndex = (this.currentPage - 1) * this.itemsPerPage;
      const endIndex = startIndex + this.itemsPerPage;
      this.paginatedItems = this.filteredRetailerRecords.slice(startIndex, endIndex);
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 310; // Adjust for header and toolbar
    }
  }
};
